#include <stdio.h>
#include <stdlib.h>

static long long pos[100005];

static int find(const long long *arr, int n, long long key) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + ((hi - lo) >> 1);
        if (arr[mid] == key) return 1;
        else if (arr[mid] < key) lo = mid + 1;
        else hi = mid - 1;
    }
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *L = (long long *)malloc((size_t)n * sizeof(long long));
    long long S = 0;
    for (int i = 0; i < n; i++) {
        scanf("%lld", &L[i]);
        S += L[i];
    }

    /* Um retangulo inscrito no circulo tem diagonais que sao diametros.
       Logo, precisamos de pelo menos dois pares de arvores antipodais. */

    /* Se o perimetro total e impar, metade nao e inteira: impossivel */
    if (S % 2 != 0) {
        printf("N\n");
        free(L);
        return 0;
    }

    /* Posicoes acumuladas das arvores na circunferencia (ja ordenadas) */
    pos[0] = 0;
    for (int i = 1; i < n; i++) pos[i] = pos[i - 1] + L[i - 1];

    long long half = S / 2;
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        long long t = pos[i] + half;
        if (t >= S) t -= S;
        if (find(pos, n, t)) cnt++;  /* cada par antipodal conta 2 vezes */
    }

    printf(cnt >= 4 ? "S\n" : "N\n");
    free(L);
    return 0;
}
